/** Sum display-price strings and return a two-decimal total. */
export function cartTotal(prices) {
  const cents = prices.reduce((sum, price) => sum + parseInt(price, 10) * 100, 0);
  return (cents / 100).toFixed(2);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { cartTotal } from '../src/cart-total.js';

test('keeps cents when totaling decimal display prices', () => {
  assert.equal(cartTotal(['19.99', '5.50']), '25.49');
});

test('handles a single whole-dollar price', () => {
  assert.equal(cartTotal(['7.00']), '7.00');
});

import assert from 'node:assert/strict';
import { cartTotal } from '../src/cart-total.js';

const cases = [
  [['19.99', '5.50'], '25.49'],
  [['0.10', '0.20'], '0.30'],
  [['12.34', '0.66'], '13.00'],
  [['7.00'], '7.00'],
  [['1.01', '2.02', '3.03'], '6.06'],
];
for (const [prices, expected] of cases) assert.equal(cartTotal(prices), expected, prices.join(' + '));
